export const OFFICIAL_TEMPLATE_TYPE_KEYS = Object.freeze(
  Object.keys(OFFICIAL_TEMPLATES),
) as readonly string[];

export function hasOfficialTemplate(type: string): boolean {
  return type.trim().toLowerCase() in OFFICIAL_TEMPLATES;
}
